def find_enclosed_rectangles(grid):
    """Find all rectangular blocks of one color enclosed by a different color"""
    h, w = len(grid), len(grid[0])
    enclosed_blocks = []

    for r1 in range(h):
        for c1 in range(w):
            # Skip if already checked
            already_checked = False
            for (start_r, start_c), (end_r, end_c), _ in enclosed_blocks:
                if r1 <= end_r and c1 <= end_c:
                    already_checked = True
                    break
            if already_checked:
                continue

            color = grid[r1][c1]
            found_exact = False
            # Try to extend the rectangle
            for r2 in range(r1, h):
                for c2 in range(c1, w):
                    # Check if all cells in rectangle [r1:r2+1, c1:c2+1] are same color
                    if not all(grid[i][j] == color for i in range(r1, r2+1) for j in range(c1, c2+1)):
                        continue

                    # For non-minimal rectangles (extended), check enclosure
                    if r2 == r1 and c2 == c1:
                        # Single pixel - check its enclosure
                        if r1 > 0 and all(grid[r1-1][c1] != color):
                            pass  # OK
                        elif c1 > 0 and all(grid[r1][c1-1] != color):
                            pass  # OK
                        else:
                            continue  # Not enclosed

                    # Check if fully enclosed by different color
                    if (r1 > 0 and all(grid[r1-1][j] != color for j in range(c1, c2+1)) and
                        (r2 < h-1 and all(grid[r2+1][j] != color for j in range(c1, c2+1)) or True) and
                        (c1 > 0 and all(grid[i][c1-1] != color for i in range(r1, r2+1)) or True) and
                        (c2 < w-1 and all(grid[i][c2+1] != color for i in range(r1, r2+1)) or True)):
                        pass  # Fully enclosed
                    else:
                        # Check bottom and right more carefully
                        if r2 < h-1 and any(grid[r2+1][j] == color for j in range(c1, c2+1)):
                            continue  # Touches same color at bottom
                        if c2 < w-1 and any(grid[i][c2+1] == color for i in range(r1, r2+1)):
                            continue  # Touches same color at right
                        # Check top and left
                        if r1 > 0 and any(grid[r1-1][j] == color for j in range(c1, c2+1)):
                            continue  # Touches same color at top
                        if c1 > 0 and any(grid[i][c1-1] == color for i in range(r1, r2+1)):
                            continue  # Touches same color at left

                    # Found an enclosed rectangle (non-minimal!)
                    enclosed_blocks.append(((r1, c1), (r2, c2), color))
                    print(f"  Found: color={color}, rows {r1}-{r2}, cols {c1}-{c2}")
                    found_exact = True
                    break
                if found_exact:
                    break

    return enclosed_blocks

